	app1.filter("iq_array_refactor",function(){
    	/*
    	 * 示例：{{ XXX | iq_array_refactor:"[.id][.name]"}}
    	 * XXX为数组[obj1,obj2]
    	 * 将按照expression的模式显示数组  其中[.属性]替换数组元素的属性值
    	 * id name为可选，也可替换
    	 * 如 任意1[.id]任意2[.name]任意3 显示 : 任意1+"obj1.id"+任意2+"obj1.name"+任意3,任意1+"obj2.id"+任意2+"obj2.name"+任意3
    	 *
    	 * XXX 为[{id:"id1",username:"xuchao1"},{id:"id2",username:"xuchao2"},{id:"id2",username:"xuchao2"}]
    	 * expression为[.username]([.id])
    	 * 显示结果为：xuchao1(id1),xuchao2(id2),xuchao2(id2)
    	 */
	    return function(array,expression){
//	        console.log(array)
	        var list = [];
	        var matchs = expression.match(/\[.[.\w]+\]/g);
	        var replaces = [];
	        for(var j = 0;j<matchs.length;j++){
	            var sub = matchs[j].slice(1,-1);
	            replaces.push(sub.split("."));
	        }
	        for(var i = 0;i<array.length;i++){
	            var str = expression;
	            for(var j = 0;j<matchs.length;j++){
	                var subs = replaces[j]
	                var tmp = array[i];
	                for(var k = 0;k<subs.length;k++){
	                    if(subs[k]&&tmp){
	                        tmp = tmp[subs[k]];
	                    }
	                }
	                str = str.replace(matchs[j],tmp);
	            }
	            list.push(str);
	        }
	        return list.join(",")
	    }
	})
	app1.filter("departmentfilter",function(){
		return function(key,expression){
			if(angular.isArray(key)){
				var tmp = [];
				for(var i = 0;i<key.length;i++){
					if(key[i].department && key[i].department.id == expression){
						tmp.push(key[i]);
					}
				}
				return tmp;
			}else{
				if(key.department && key.department.id == expression){
					return key;
				}else{
					return null;
				}
			}
		}
	})
    app1.filter("iq_refactor", function() {
    	/*
    	 * 示例：{{ XXX | iq_refactor:"男,true;女,false"}}
    	 * array_str pattern val,key;val,key;key,value
    	 */
    	var refactor = function(key,expression){
    		if(angular.isString(expression)){
	    		key += "";
	    		var tmp = expression+";";
	    		if(!!key){

		    		var r = new RegExp("([^;,]+),"+key+";")
		    		var result = tmp.match(r);
		    		if(result){
		    			return result[1];
		    		}
	    		}
    		}else if(!!expression && !!expression.value && expression.formula != true){
	    		key += "";

	    		if(!!key){
	    			if(angular.isString(expression.value)){
		    			var separator1 = expression.separator1 || ",";
		    			var separator2 = expression.separator2 || ";";
			    		var tmp = expression.value;
		    			var list = tmp.split(separator2);
		    			for(var i = 0;i < list.length;i++){
		    				var list1 = list[i].split(separator1);
		    				if(list1[1] == key){
		    					return list1[0];
		    				}
			    		}
	    			}else if(angular.isObject(expression.value)){
	    				var tmp = angular.copy(expression.value)
	    				for(var i in tmp){
	    					if(tmp[i]==key){
	    						return i;
	    					}
	    				}
	    			}
	    		}
	    		if(expression.def_val){
	    			return expression.def_val;
	    		}
    		}else if(!!expression && !!expression.value && expression.formula == true){
    			//使用key的表达式，匹配第一个满足的表达式，返回对应显示值
	    		key += "";

	    		if(!!key){
	    			if(angular.isString(expression.value)){
		    			var separator1 = expression.separator1 || ",";
		    			var separator2 = expression.separator2 || ";";
			    		var tmp = expression.value;
		    			var list = tmp.split(separator2);
		    			for(var i = 0;i < list.length;i++){
		    				var list1 = list[i].split(separator1);
		    				var result = eval(list1[1]);
		    				if(result){
		    					return list1[0];
		    				}
			    		}
	    			}
	    			else if(angular.isObject(expression.value)){
	    				var tmp = angular.copy(expression.value)
	    				for(var i in tmp){
	    					var result = eval(tmp[i]);
	    					if(result){
	    						return i;
	    					}
	    				}
	    			}
	    		}
	    		if(expression.def_val){
	    			return expression.def_val;
	    		}
    		}
    		return ""
    	}
    	return refactor;
    })
    //金钱转大写汉字
    app1.filter("iq_num2CN",function(){
    	var TransformNumberIntoCHN = function(themoney) {
    		var money = themoney+'';
    		var flag = 1;  //正负钱数标志位，1--正数，0--负数
    		var arr = new Array();
    		arr = money.split(".");
    		var intpart = arr[0].replace(/(.)(?=[^$])/g,"$1,").split(",");
    		if(intpart[0] === '-'){
    			flag = 0;
    			var str = "";
    			for(var i=1;i<intpart.length;i++){
    				str += intpart[i];
    			}
    			if(arr[1] !== '' || arr[1] !== null){
    				money = str+"."+arr[1];
    			}
    			else{
    				money = str;
    			}
    		}

    		if(money == '0.00' || money == '0'){
    			return "零元整";
    		}
    		else{
    			var number = money;
        	    var unit = "仟佰拾亿仟佰拾万仟佰拾元角分", str = "";
        	    number += "00";
        	    var point = number.indexOf('.');
        	    if (point >= 0) {
        	        number = number.substring(0, point) + number.substr(point + 1, 2);
        	    }
        	    unit = unit.substr(unit.length - number.length);
        	    for (var i = 0; i < number.length; i++) {
        	        str += '零壹贰叁肆伍陆柒捌玖'.charAt(number.charAt(i)) + unit.charAt(i);
        	    }
        	    //document.getElementById(idCHN).value = str.replace(/零(仟|佰|拾|角)/g, "零").replace(/(零)+/g, "零").replace(/零(万|亿|元)/g, "$1").replace(/(亿)万|壹(拾)/g, "$1$2").replace(/^元零?|零分/g, "").replace(/元$/g, "元整");
        	    var moneyCN = str.replace(/零(仟|佰|拾|角)/g, "零").replace(/(零)+/g, "零").replace(/零(万|亿|元)/g, "$1").replace(/(亿)万|(拾)/g, "$1$2").replace(/^元零?|零分/g, "").replace(/元$/g, "元整");
        	    if(flag === 0){
        	    	moneyCN = '负'+moneyCN;
        	    }
        	    return moneyCN;
    		}
    	}
    	return TransformNumberIntoCHN;
    })

