    var $iq_queue = function(){
    	var queue = {};
    	this.$get = ["$rootScope", "$q", function($rootScope, $q) {
    		return {
    			get:function(str){
    				if(!queue[str]){
        				var def = $q.defer();
        				queue[str] = def;
    				}
    				return queue[str];
    			}
    		}
    	}]
    }
