var CIAPP = CIAPP || {};

CIAPP.namespace = function (ns_string) {
    var parts = ns_string.split('.'),
    parent = CIAPP,
    i;

    //剥离最前面的冗余全局变量
    if(parts[0] === 'CIAPP'){
        parts = parts.slice(1);
    }
    for(i = 0, len = parts.length; i < len; i +=1){
        if(typeof parent[parts[i]] === "undefined"){
            parent[parts[i]] = {};
        }
        parent = parent[parts[i]];
    }
    return parent;
};


CIAPP.namespace('CIAPP.utils.changeColor');


CIAPP.utils.changeColor = (function(){

    //private property
    var doc =  document,
    changeCon,
    changeClass,
    changeStr,
    children,
    pattern,
    newString,

    traversal = function(children) {
        var i, len;

        for(i = 0, len = children.length; i < len; i += 1) {
            newNodeText = '';

            if(children[i].children){
                traversal(children[i].childNodes);
            }

            //文本内容部分
            if(children[i].nodeType === 3 ){

                pattern = new RegExp( changeStr, "g" );

                newString = children[i].nodeValue.replace( pattern
                            , "<em class="+changeClass+">"+ changeStr +"</em>");


                // 如果匹配指定字符串
               if( pattern.test( children[i].nodeValue ) ){
                thisNode = children[i];
                children[i].parentNode.innerHTML = newString;

                }
            }
    

        }
    },

    init = function(classname, class_chg, str){
        changeCon = doc.getElementsByClassName(classname),
        changeClass = class_chg;
        changeStr = str;
        
        for( var i = 0, len = changeCon.length; i < len; i += 1){
        	children = changeCon[i].childNodes;
        	traversal(children);
        }
    };

    return {
        init : init,
        change : traversal
    }

}());

